    const chunkLen = (bytes[pos]<<24)|(bytes[pos+1]<<16)|(bytes[pos+2]<<8)|bytes[pos+3];
    const ctype = String.fromCharCode(bytes[pos+4], bytes[pos+5], bytes[pos+6], bytes[pos+7]);
    if (ctype === 'IDAT') {
      idatChunks.push(bytes.subarray(pos+8, pos+8+chunkLen));
    }
    pos += 12 + chunkLen;
    if (ctype === 'IEND') break;
  }
  // Concatenate IDAT
